QUESTION_KINDS = ["identity", "definition", "classification", "composition", "relationship", "state", "lifecycle", "temporal", "spatial", "provenance", "ownership", "authority", "requirement", "constraint", "process", "event", "measurement", "evidence", "quality", "validation", "security", "privacy", "retention", "access", "exception", "interoperability", "decision"]


def structure():
    bundles = []
    n = 0
    for bid, bname, bdesc, rationale, brefs, layers in STRUCTURE:
        layer_rows = []
        for lid, lname, ldesc, lrefs, findings in layers:
            finding_rows = []
            for fid, fname, fdesc, primary_kind, frefs, value_kind, required, serial in findings:
                k2 = QUESTION_KINDS[(n + 9) % len(QUESTION_KINDS)]
                k3 = QUESTION_KINDS[(n + 19) % len(QUESTION_KINDS)]
                n += 1
                questions = [
                    {"id": f"{fid}-q01", "text": f"What governed skill assertion is recorded for {fname.lower()}, for which skill identity, release, task context, agent environment and lifecycle state?", "kind": primary_kind, "answer_data": [fname, "skill identity and release", "task context, environment and state"]},
                    {"id": f"{fid}-q02", "text": f"Which source, steward, standard, validation or evaluation establishes {fname.lower()}, with what evidence, confidence, freshness and limitations?", "kind": k2, "answer_data": ["source, steward and standard", "validation or evaluation evidence", "confidence, freshness and limitations"]},
                    {"id": f"{fid}-q03", "text": f"Which authority, safety, compatibility or change rule governs {fname.lower()}, and how are permissions, predecessors, successors and external bindings preserved?", "kind": k3, "answer_data": ["authority, safety and compatibility rule", "permitted action and effective time", "predecessor, successor and external reference"]},
                ]
                data_elements = [{"id": f"{fid}-data", "name": f"{fname} assertion", "description": f"Structured agent-skill answer data for {fname.lower()}, including release, context, authority, status and provenance.", "value_kind": value_kind, "cardinality": "1" if required else "0..n", "required": required, "source_refs": frefs}]
                artifacts = [{"id": f"{fid}-artifact", "name": f"{fname} record", "description": f"Versioned skill record supporting {fname.lower()} with provenance, validation and access marking.", "media_or_form": ["structured skill assertion", "instruction, contract or evidence statement", "resolvable package or external-system index"], "serial": serial, "identity_strategy": "Authoritative skill registry or master-system identifier first; otherwise a Dimension-governed UUID or ULID.", "source_refs": frefs}]
                finding_rows.append({"id": fid, "name": fname, "description": fdesc, "source_refs": frefs, "questions": questions, "data_elements": data_elements, "artifacts": artifacts, "inline_only_rationale": None})
            layer_rows.append({"id": lid, "name": lname, "description": ldesc, "source_refs": lrefs, "findings": finding_rows})
        bundles.append({"id": bid, "name": bname, "description": bdesc, "rationale": rationale, "source_refs": brefs, "layers": layer_rows})
    return {"bundles": bundles}


